import string

# Parse tree array (already offset)
tree_lines = open('/tmp/tree_hex.txt').read().splitlines()
tree = []
for line in tree_lines:
    for x in line.split():
        v = int(x, 16)
        tree.append(v)

# identify first nonzero row (skip zeros)
first_nonzero = 0
for idx, value in enumerate(tree):
    if value != 0:
        first_nonzero = idx
        break

# Our tree starts at first_nonzero
trimmed_tree = tree[first_nonzero:]

# Map node indices to ASCII if possible
ascii_map = {}
for idx, val in enumerate(trimmed_tree):
    if 32 <= val < 127:
        ascii_map[idx] = chr(val)
    else:
        ascii_map[idx] = '.' # not printable

# Parse flag index sequence
flagseq_lines = open('/tmp/flagseq_hex.txt').read().splitlines()
flag_indices = []
for line in flagseq_lines:
    for x in line.split():
        flag_indices.append(int(x, 16))

flag_chars = []
issues = []
for idx in flag_indices[:0x21]:  # typically 33 for flag{...}
    if idx == 0xFFFFFFFF:
        flag_chars.append('?')
        issues.append('Index is 0xFFFFFFFF')
    elif idx >= len(trimmed_tree):
        flag_chars.append('?')
        issues.append('Out-of-bounds index: %d' % idx)
    else:
        flag_chars.append(ascii_map[idx])

flag = ''.join(flag_chars)
print('Reconstructed flag: flag{%s}' % flag)
if issues:
    print('Issues:', issues)

