import struct
import string

def parse_tree(path, start_row=2):
    with open(path, 'rb') as f:
        f.seek(0x301020)
        # Read more than enough, short arrays will handle end
        data = f.read(0x400)
    ints = list(struct.iter_unpack('<I', data))
    # Flatten and skip zeros in the first rows
    arr = [x[0] for x in ints]
    tree = []
    found_first_data = False
    for i, val in enumerate(arr):
        if not found_first_data:
            if val != 0:
                found_first_data = True
                tree.append(val)
        else:
            tree.append(val)
    # Now map present indices to ASCII if printable
    printable_map = {}
    for i, v in enumerate(tree):
        c = v & 0xff
        if 32 <= c <= 126:
            printable_map[i] = chr(c)
        else:
            printable_map[i] = '.'
    return tree, printable_map

def parse_indices(path):
    with open(path, 'rb') as f:
        f.seek(0x3014e0)
        data = f.read(0x100)  # up to 64 indices
    idxs = list(struct.iter_unpack('<I', data))
    return [x[0] for x in idxs if x[0] != 0]

def main():
    tree, printable_map = parse_tree('/home/ctfplayer/ctf_files/beleaf')
    flag_indices = parse_indices('/home/ctfplayer/ctf_files/beleaf')
    flag_chars = []
    for idx in flag_indices[:33]:
        if idx == 0xffffffff:
            flag_chars.append('?')
        elif idx >= len(tree):
            flag_chars.append('!')
        else:
            ch = printable_map.get(idx, '.')
            flag_chars.append(ch)
    flag = ''.join(flag_chars)
    print(f'flag{{{flag}}}')

if __name__ == '__main__':
    main()

